template:
otelcol.processor.transform "${1:default}" {
  output {
    metrics = []
    logs = []
    traces = []
  }
  debug_metrics {
    $0
  }
  log_statements {
    context = "${2}"
    statements = "${3}"
  }
  metric_statements {
    context = "${2}"
    statements = "${3}"
  }
  statements {
    context = "${2}"
    statements = "${3}"
  }
  trace_statements {
    context = "${2}"
    statements = "${3}"
  }

  // Exported fields:
  // - input (otelcol.Consumer): A value that other components can use to send telemetry data to.
}
